uint64_t add_native32_object(Scene &scene,const SculptObject &object,const char *name,Vec3 position){auto id=scene.add(name,Volume{});auto copy=object;copy.id=id;copy.name=name;copy.transform.position={position.x,position.y,position.z};copy.transform.scale=.48f;scene.object(id)=std::move(copy);return id;}
struct Mixed32 {Scene scene;uint64_t first=0,second=0,plain=0,legacy=0;};
Mixed32 mixed32(){
 auto source=native_grid(Material::AlphaMode::Opaque);auto retained=native_split(source);Mixed32 mixed;mixed.scene=retained.snapshot();mixed.first=mixed.scene.active().id;mixed.scene.active().transform.position={-.65f,.4f,0};mixed.scene.active().transform.scale=.48f;
 auto ldr=retained.active();ldr.painted=detail::EmissionExportAccess::without_emission(*ldr.painted);ldr.material.emissive={};mixed.plain=add_native32_object(mixed.scene,ldr,"No-current-emission native32",{0,.4f,0});
 auto different=retained.active();different.painted=different.painted->snapshot();different.painted->select_layer(different.painted->layers().at(1).id);PaintSettings ink;ink.front_only=false;ink.channel=PaintChannel::Emission;ink.emission_units=PaintEmissionUnits::Physical;ink.emission={.02f,3.1f,.006f};Brush b;b.from=b.to={-.23f,.14f,0};b.normal={0,0,1};b.radius=.22f;b.strength=.83f;different.painted->begin_stroke();different.painted->stamp(b,ink);check(different.painted->end_stroke(),"Mixed native32 second object has genuinely different float detail");mixed.second=add_native32_object(mixed.scene,different,"Independent float native32",{.65f,.4f,0});
 auto old=source.active();old.material.emissive={3.7f,.015f,.08f};mixed.legacy=add_native32_object(mixed.scene,old,"Legacy UV0 physical field",{-.4f,-.4f,0});
 mixed.scene.select(mixed.first);mixed.scene.validate();return mixed;
}
